-- Per-value membership union implements COUNT(DISTINCT) without duplicating base rows by world.
WITH input AS (SELECT CASE WHEN (ss_quantity BETWEEN 0 AND 5 AND (ss_list_price BETWEEN 8 AND 18 OR ss_coupon_amt BETWEEN 459 AND 1459 OR ss_wholesale_cost BETWEEN 57 AND 77)) THEN 1 WHEN (ss_quantity BETWEEN 6 AND 10 AND (ss_list_price BETWEEN 90 AND 100 OR ss_coupon_amt BETWEEN 2323 AND 3323 OR ss_wholesale_cost BETWEEN 31 AND 51)) THEN 2 WHEN (ss_quantity BETWEEN 11 AND 15 AND (ss_list_price BETWEEN 142 AND 152 OR ss_coupon_amt BETWEEN 12214 AND 13214 OR ss_wholesale_cost BETWEEN 79 AND 99)) THEN 3 WHEN (ss_quantity BETWEEN 16 AND 20 AND (ss_list_price BETWEEN 135 AND 145 OR ss_coupon_amt BETWEEN 6071 AND 7071 OR ss_wholesale_cost BETWEEN 38 AND 58)) THEN 4 WHEN (ss_quantity BETWEEN 21 AND 25 AND (ss_list_price BETWEEN 122 AND 132 OR ss_coupon_amt BETWEEN 836 AND 1836 OR ss_wholesale_cost BETWEEN 17 AND 37)) THEN 5 WHEN (ss_quantity BETWEEN 26 AND 30 AND (ss_list_price BETWEEN 154 AND 164 OR ss_coupon_amt BETWEEN 7326 AND 8326 OR ss_wholesale_cost BETWEEN 7 AND 27)) THEN 6 END AS bucket, ss_list_price AS price, priv_hash(hash(ss_customer_sk)) AS membership
FROM main.store_sales JOIN main.customer ON ss_customer_sk=c_customer_sk WHERE (ss_quantity BETWEEN 0 AND 5 AND (ss_list_price BETWEEN 8 AND 18 OR ss_coupon_amt BETWEEN 459 AND 1459 OR ss_wholesale_cost BETWEEN 57 AND 77)) OR (ss_quantity BETWEEN 6 AND 10 AND (ss_list_price BETWEEN 90 AND 100 OR ss_coupon_amt BETWEEN 2323 AND 3323 OR ss_wholesale_cost BETWEEN 31 AND 51)) OR (ss_quantity BETWEEN 11 AND 15 AND (ss_list_price BETWEEN 142 AND 152 OR ss_coupon_amt BETWEEN 12214 AND 13214 OR ss_wholesale_cost BETWEEN 79 AND 99)) OR (ss_quantity BETWEEN 16 AND 20 AND (ss_list_price BETWEEN 135 AND 145 OR ss_coupon_amt BETWEEN 6071 AND 7071 OR ss_wholesale_cost BETWEEN 38 AND 58)) OR (ss_quantity BETWEEN 21 AND 25 AND (ss_list_price BETWEEN 122 AND 132 OR ss_coupon_amt BETWEEN 836 AND 1836 OR ss_wholesale_cost BETWEEN 17 AND 37)) OR (ss_quantity BETWEEN 26 AND 30 AND (ss_list_price BETWEEN 154 AND 164 OR ss_coupon_amt BETWEEN 7326 AND 8326 OR ss_wholesale_cost BETWEEN 7 AND 27))),
stats AS (SELECT bucket,tpcds_avg(membership,price) AS average,tpcds_count(membership,price) AS n FROM input GROUP BY bucket),
unique_prices AS (SELECT bucket,price,bit_or(membership) AS membership FROM input WHERE price IS NOT NULL GROUP BY bucket,price),
unique_counts AS (SELECT bucket,tpcds_count(membership,1) AS n FROM unique_prices GROUP BY bucket),
expanded AS (SELECT world,bucket,average[world+1] AS average,coalesce(stats.n[world+1],0) AS n,coalesce(unique_counts.n[world+1],0) AS nd
FROM (VALUES(1),(2),(3),(4),(5),(6)) b(bucket) CROSS JOIN range(64) worlds(world) LEFT JOIN stats USING(bucket) LEFT JOIN unique_counts USING(bucket))
SELECT world,max(average) FILTER (WHERE bucket=1) AS b1_lp, max(n) FILTER (WHERE bucket=1) AS b1_cnt, max(nd) FILTER (WHERE bucket=1) AS b1_cntd, max(average) FILTER (WHERE bucket=2) AS b2_lp, max(n) FILTER (WHERE bucket=2) AS b2_cnt, max(nd) FILTER (WHERE bucket=2) AS b2_cntd, max(average) FILTER (WHERE bucket=3) AS b3_lp, max(n) FILTER (WHERE bucket=3) AS b3_cnt, max(nd) FILTER (WHERE bucket=3) AS b3_cntd, max(average) FILTER (WHERE bucket=4) AS b4_lp, max(n) FILTER (WHERE bucket=4) AS b4_cnt, max(nd) FILTER (WHERE bucket=4) AS b4_cntd, max(average) FILTER (WHERE bucket=5) AS b5_lp, max(n) FILTER (WHERE bucket=5) AS b5_cnt, max(nd) FILTER (WHERE bucket=5) AS b5_cntd, max(average) FILTER (WHERE bucket=6) AS b6_lp, max(n) FILTER (WHERE bucket=6) AS b6_cnt, max(nd) FILTER (WHERE bucket=6) AS b6_cntd FROM expanded GROUP BY world ORDER BY world;
